initJs:
function(container, apiUrl, tables) {
  let products = [];
  let categories = [];
  let stores = [];
  let orderItems = [];
  let selectedProduct = null;

  // 初期化
  async function init() {
    try {
      // 各テーブルからデータを取得
      products = await window.aivicApi.list(2) || []; // 商品マスタ
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ

      // 店舗選択肢を設定
      const storeSelect = container.querySelector('#store-select');
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });

      // カテゴリ一覧を作成（商品から抽出）
      const categorySet = new Set();
      products.forEach(product => {
        if (product.商品カテゴリID) {
          categorySet.add(product.商品カテゴリID);
        }
      });
      categories = Array.from(categorySet);

      // カテゴリ選択肢を設定
      const categorySelect = container.querySelector('#category-select');
      categories.forEach(categoryId => {
        const option = document.createElement('option');
        option.value = categoryId;
        option.textContent = `カテゴリ ${categoryId}`;
        categorySelect.appendChild(option);
      });

      // 発注日を今日に設定
      const today = new Date().toISOString().split('T')[0];
      container.querySelector('#order-date').value = today;

      // 商品一覧を初期表示
      renderProductList(products.filter(p => p.有効フラグ));

    } catch (error) {
      showError('データの初期化に失敗しました: ' + error.message);
    }
  }

  // 商品一覧を描画
  function renderProductList(productList) {
    const tbody = container.querySelector('#product-list-tbody');
    tbody.innerHTML = productList.map(product => `
      <tr data-id="${product.商品ID}">
        <td>${product.商品名 || ''}</td>
        <td>${product.商品コード || ''}</td>
        <td>¥${(product.単価 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary select-product-btn" data-id="${product.商品ID}">選択</button>
        </td>
      </tr>
    `).join('');
  }

  // 発注一覧を描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list-tbody');
    tbody.innerHTML = orderItems.map((item, index) => `
      <tr>
        <td>${item.商品名}</td>
        <td>${item.商品コード}</td>
        <td>${item.発注数量}</td>
        <td>¥${item.単価.toLocaleString()}</td>
        <td>¥${(item.発注数量 * item.単価).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary remove-item-btn" data-index="${index}">削除</button>
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 発注総額を更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // AI予測数量を取得（模擬）
  async function getAIPrediction(productId, storeId) {
    try {
      // 需要予測結果テーブルから該当データを検索
      const predictions = await window.aivicApi.list(9) || []; // 需要予測結果
      const prediction = predictions.find(p => 
        p.商品ID === productId && 
        p.店舗ID === storeId && 
        p.予測ステータス === '完了'
      );

      if (prediction) {
        return {
          quantity: prediction.推奨発注数量 || prediction.予測数量 || 0,
          accuracy: prediction.予測精度 || 85,
          basis: `過去の売上データ、季節性、天候要因を分析した結果です。予測精度: ${prediction.予測精度 || 85}%`
        };
      } else {
        // デフォルト予測値を返す
        return {
          quantity: Math.floor(Math.random() * 50) + 10,
          accuracy: 75,
          basis: '過去3ヶ月の売上平均、曜日別傾向、季節要因を考慮した予測です。'
        };
      }
    } catch (error) {
      return {
        quantity: 20,
        accuracy: 70,
        basis: '基本的な需要予測アルゴリズムによる推定値です。'
      };
    }
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return false;
    }

    // 過去日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (orderDate < today) {
      showError('発注日に過去の日付は設定できません');
      return false;
    }

    // 納期チェック
    if (deliveryDate < orderDate) {
      showError('納期は発注日以降の日付を設定してください');
      return false;
    }

    if (orderItems.length === 0) {
      showError('発注する商品を選択してください');
      return false;
    }

    return true;
  }

  // イベントリスナー設定

  // 商品検索
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const categoryId = container.querySelector('#category-select').value;

    let filteredProducts = products.filter(p => p.有効フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);

    if (filteredProducts.length === 0) {
      container.querySelector('#product-list-tbody').innerHTML = 
        '<tr><td colspan="4" style="text-align: center; color: var(--text-muted);">該当する商品が見つかりませんでした</td></tr>';
    }
  });

  // カテゴリ選択変更
  container.querySelector('#category-select').addEventListener('change', () => {
    container.querySelector('#btn-search').click();
  });

  // 商品選択
  container.addEventListener('click', async (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      selectedProduct = products.find(p => p.商品ID === productId);

      if (selectedProduct) {
        // 商品選択エリアを表示
        const quantityArea = container.querySelector('#quantity-setting-area');
        quantityArea.style.display = 'block';

        container.querySelector('#selected-product-name').textContent = selectedProduct.商品名;

        // AI予測を取得
        const storeId = container.querySelector('#store-select').value;
        if (storeId) {
          const prediction = await getAIPrediction(productId, storeId);
          container.querySelector('#ai-predicted-quantity').textContent = prediction.quantity;
          container.querySelector('#manual-quantity').value = prediction.quantity;

          // 予測根拠を保存
          selectedProduct.predictionBasis = prediction.basis;
        }
      }
    }

    // 発注リストに追加
    const addBtn = e.target.closest('#btn-add-to-order');
    if (addBtn && selectedProduct) {
      const quantity = parseInt(container.querySelector('#manual-quantity').value);

      if (!quantity || quantity < 0) {
        showError('手動調整数量は0以上の値を入力してください');
        return;
      }

      // 既存アイテムをチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === selectedProduct.商品ID);

      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: selectedProduct.商品ID,
          商品名: selectedProduct.商品名,
          商品コード: selectedProduct.商品コード,
          発注数量: quantity,
          単価: selectedProduct.単価 || 0
        });
      }

      renderOrderList();

      // フォームをリセット
      container.querySelector('#quantity-setting-area').style.display = 'none';
      container.querySelector('#manual-quantity').value = '';
      selectedProduct = null;
    }

    // 発注リストから削除
    const removeBtn = e.target.closest('.remove-item-btn');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      orderItems.splice(index, 1);
      renderOrderList();
    }

    // 予測根拠表示
    const basisBtn = e.target.closest('#btn-prediction-basis');
    if (basisBtn && selectedProduct) {
      const modal = container.querySelector('#prediction-basis-modal');
      const content = container.querySelector('#prediction-basis-content');
      content.innerHTML = `
        <div style="margin-bottom: 16px;">
          <h4 style="color: var(--text); margin-bottom: 8px;">商品: ${selectedProduct.商品名}</h4>
          <p style="color: var(--text-muted);">${selectedProduct.predictionBasis || 'AI予測根拠データを取得中...'}</p>
        </div>
        <div style="background: var(--bg-main); padding: 12px; border-radius: 4px;">
          <h5 style="color: var(--text); margin-bottom: 8px;">予測要因</h5>
          <ul style="color: var(--text-muted); margin: 0; padding-left: 20px;">
            <li>過去3ヶ月の売上トレンド</li>
            <li>曜日別売上パターン</li>
            <li>季節性要因</li>
            <li>天候・イベント影響</li>
          </ul>
        </div>
      `;
      modal.classList.remove('hidden');
    }

    // 在庫状況確認
    const stockBtn = e.target.closest('#btn-stock-check');
    if (stockBtn && selectedProduct) {
      const modal = container.querySelector('#stock-check-modal');
      const content = container.querySelector('#stock-info-content');

      // 模擬在庫データ
      const currentStock = Math.floor(Math.random() * 100);
      const status = currentStock > 50 ? '十分' : currentStock > 20 ? '注意' : '不足';
      const statusColor = currentStock > 50 ? '#4CAF50' : currentStock > 20 ? '#FF9800' : '#F44336';

      content.innerHTML = `
        <div style="margin-bottom: 16px;">
          <h4 style="color: var(--text); margin-bottom: 8px;">商品: ${selectedProduct.商品名}</h4>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div>
              <label style="color: var(--text-muted); font-size: 14px;">現在在庫数量</label>
              <div style="color: var(--text); font-size: 24px; font-weight: bold;">${currentStock}個</div>
            </div>
            <div>
              <label style="color: var(--text-muted); font-size: 14px;">在庫ステータス</label>
              <div style="color: ${statusColor}; font-size: 18px; font-weight: bold;">${status}</div>
            </div>
          </div>
          <div style="margin-top: 12px; color: var(--text-muted); font-size: 14px;">
            最終更新: ${new Date().toLocaleString()}
          </div>
        </div>
      `;
      modal.classList.remove('hidden');
    }

    // 過去実績参照
    const pastBtn = e.target.closest('#btn-past-records');
    if (pastBtn && selectedProduct) {
      const modal = container.querySelector('#past-records-modal');
      modal.classList.remove('hidden');
    }

    // 過去実績データ取得
    const getPastDataBtn = e.target.closest('#btn-get-past-data');
    if (getPastDataBtn && selectedProduct) {
      const period = container.querySelector('#past-period-select').value;
      const content = container.querySelector('#past-records-content');

      // 模擬過去実績データ
      const pastData = [];
      for (let i = 0; i < parseInt(period); i++) {
        const date = new Date();
        date.setMonth(date.getMonth() - i);
        pastData.push({
          month: date.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long' }),
          sales: Math.floor(Math.random() * 200) + 50,
          orders: Math.floor(Math.random() * 150) + 30
        });
      }

      content.innerHTML = `
        <h4 style="color: var(--text); margin-bottom: 16px;">商品: ${selectedProduct.商品名}</h4>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>期間</th>
                <th>売上数量</th>
                <th>発注数量</th>
              </tr>
            </thead>
            <tbody>
              ${pastData.map(data => `
                <tr>
                  <td>${data.month}</td>
                  <td>${data.sales}個</td>
                  <td>${data.orders}個</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }

    // モーダル閉じる
    const closeModalBtns = [
      '#btn-close-prediction-modal',
      '#btn-close-stock-modal', 
      '#btn-close-past-modal'
    ];

    closeModalBtns.forEach(selector => {
      const btn = e.target.closest(selector);
      if (btn) {
        const modal = btn.closest('[id$="-modal"]');
        modal.classList.add('hidden');
      }
    });

    // 発注書作成
    const createOrderBtn = e.target.closest('#btn-create-order');
    if (createOrderBtn) {
      if (!validateForm()) return;

      try {
        const storeId = container.querySelector('#store-select').value;
        const orderDate = container.querySelector('#order-date').value;
        const deliveryDate = container.querySelector('#delivery-date').value;

        // 各商品の発注データを保存
        for (const item of orderItems) {
          const orderData = {
            店舗ID: storeId,
            商品ID: item.商品ID,
            発注日: orderDate + 'T00:00:00Z',
            納期予定日: deliveryDate + 'T00:00:00Z',
            発注数量: item.発注数量,
            発注単価: item.単価,
            発注金額: item.発注数量 * item.単価,
            発注方法: '手動発注',
            発注ステータス: '発注済',
            仕入先ID: 'default-supplier',
            発注理由: 'AI需要予測に基づく発注',
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          await window.aivicApi.save(10, orderData); // 発注データテーブル
        }

        alert('発注書を正常に作成しました');
        window.showScreen('scr-1778591852463'); // 発注管理画面に遷移

      } catch (error) {
        showError('発注書の作成に失敗しました: ' + error.message);
      }
    }
  });

  // 手動調整数量のバリデーション
  container.querySelector('#manual-quantity').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value < 0) {
      showError('手動調整数量は0以上の値を入力してください');
      e.target.value = 0;
    }
  });

  // モーダル背景クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.id && e.target.id.endsWith('-modal')) {
      e.target.classList.add('hidden');
    }
  });

  // 初期化実行
  init();
}
